// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    EmergencyOracleFactory c;

    function setUp() public { c = new EmergencyOracleFactory(); }

    function testFuzz_property(address caller, bytes calldata desc) public {
        vm.assume(caller != address(0));
        vm.assume(desc.length > 0);

        Deployer d = new Deployer(caller);
        EmergencyOracleFactory localC = d.deployedC();

        vm.prank(caller);
        bool ok;
        try localC.newEmergencyOracle(string(desc)) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(localC.jojoTeam() == caller);
        } else {
            assertTrue(true);
        }
    }
}

contract Deployer {
    EmergencyOracleFactory internal deployed;
    constructor(address jojo) {
        MinimalC m = new MinimalC(jojo);
        deployed = EmergencyOracleFactory(address(m));
    }
    function deployedC() external view returns (EmergencyOracleFactory) { return deployed; }
}

contract MinimalC is EmergencyOracleFactory {
    constructor(address jojo) {
        jojoTeam = jojo;
    }
}
